## 2) Backend API (Node.js CommonJS + Express + pg) — Purchase with locking + atomic transaction

### `db.js`
```js
// db.js (CommonJS)
const { Pool } = require("pg");

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  // or configure via PGHOST/PGUSER/PGPASSWORD/PGDATABASE/PGPORT
});

module.exports = { pool };
```

### `app.js`
```js
// app.js (CommonJS)
const express = require("express");
const { pool } = require("./db");

const app = express();
app.use(express.json());

// Health check
app.get("/health", (_, res) => res.json({ ok: true }));

/**
 * POST /api/purchase
 * Body: { productId: number, quantity: number }
 *
 * Concurrency control:
 * - SELECT ... FOR UPDATE locks the product row
 * - Validation before write (overselling prevention)
 * - UPDATE + INSERT log happen in SAME transaction (atomic)
 * - Low stock alert triggers when remaining stock <= 5 (STRICT <=)
 */
app.post("/api/purchase", async (req, res) => {
  const productId = Number(req.body.productId);
  const quantity = Number(req.body.quantity);

  if (!Number.isInteger(productId) || productId <= 0) {
    return res.status(400).json({ error: "Invalid productId" });
  }
  if (!Number.isInteger(quantity) || quantity <= 0) {
    return res.status(400).json({ error: "Invalid quantity" });
  }

  const client = await pool.connect();
  try {
    await client.query("BEGIN");

    // Row-level lock prevents race conditions for the same product
    const { rows } = await client.query(
      `
      SELECT id, stock, low_stock_threshold
      FROM products
      WHERE id = $1
      FOR UPDATE
      `,
      [productId]
    );

    if (rows.length === 0) {
      await client.query("ROLLBACK");
      return res.status(404).json({ error: "Product not found" });
    }

    const product = rows[0];

    // Overselling prevention: validate BEFORE any write
    if (quantity > product.stock) {
      await client.query("ROLLBACK");
      return res.status(409).json({
        error: "Insufficient stock",
        available: product.stock,
        requested: quantity,
      });
    }

    const remainingStock = product.stock - quantity;

    // Write stock update
    await client.query(
      `UPDATE products SET stock = $1 WHERE id = $2`,
      [remainingStock, productId]
    );

    // SALE log insert (must be within the same transaction)
    await client.query(
      `
      INSERT INTO inventory_log (product_id, type, quantity, note)
      VALUES ($1, 'SALE', $2, $3)
      `,
      [productId, quantity, `Purchase deducted ${quantity}`]
    );

    // Low stock alert trigger (STRICTLY uses <= as required)
    // Requirement says: if remaining stock is <= 5, trigger an alert
    const threshold = 5; // business rule per spec (can also use product.low_stock_threshold)
    const lowStockAlertTriggered = remainingStock <= threshold;

    if (lowStockAlertTriggered) {
      // Keep it transactional so alert isn't emitted without the stock update/log being committed.
      await client.query(
        `
        INSERT INTO inventory_log (product_id, type, quantity, note)
        VALUES ($1, 'LOW_STOCK_ALERT', 1, $2)
        `,
        [productId, `Low stock alert: remaining stock = ${remainingStock} (<= ${threshold})`]
      );

      // You can also publish an event here (message queue/webhook) AFTER COMMIT in real systems.
      // For now we log it.
    }

    await client.query("COMMIT");

    return res.json({
      ok: true,
      productId,
      purchased: quantity,
      remainingStock,
      lowStockAlertTriggered,
      lowStockThresholdUsed: threshold,
    });
  } catch (err) {
    // Transaction Atomicity: any failure (including log insert failure) rolls back stock update
    try { await client.query("ROLLBACK"); } catch (_) {}
    return res.status(500).json({
      error: "Purchase failed (rolled back)",
      details: err.message,
    });
  } finally {
    client.release();
  }
});

/**
 * POST /api/restore
 * Body: { productId: number, quantity: number, reason?: string }
 *
 * Stock restoration on cancellation with "RESTOCK/RETURN" log entry.
 * Also uses FOR UPDATE for correctness under concurrency.
 */
app.post("/api/restore", async (req, res) => {
  const productId = Number(req.body.productId);
  const quantity = Number(req.body.quantity);
  const reason = typeof req.body.reason === "string" ? req.body.reason : "Cancellation/Return";

  if (!Number.isInteger(productId) || productId <= 0) {
    return res.status(400).json({ error: "Invalid productId" });
  }
  if (!Number.isInteger(quantity) || quantity <= 0) {
    return res.status(400).json({ error: "Invalid quantity" });
  }

  const client = await pool.connect();
  try {
    await client.query("BEGIN");

    const { rows } = await client.query(
      `SELECT id, stock FROM products WHERE id = $1 FOR UPDATE`,
      [productId]
    );

    if (rows.length === 0) {
      await client.query("ROLLBACK");
      return res.status(404).json({ error: "Product not found" });
    }

    const currentStock = rows[0].stock;
    const newStock = currentStock + quantity;

    await client.query(`UPDATE products SET stock = $1 WHERE id = $2`, [newStock, productId]);

    await client.query(
      `
      INSERT INTO inventory_log (product_id, type, quantity, note)
      VALUES ($1, 'RESTOCK/RETURN', $2, $3)
      `,
      [productId, quantity, reason]
    );

    await client.query("COMMIT");
    return res.json({ ok: true, productId, restored: quantity, newStock });
  } catch (err) {
    try { await client.query("ROLLBACK"); } catch (_) {}
    return res.status(500).json({ error: "Restore failed (rolled back)", details: err.message });
  } finally {
    client.release();
  }
});

const port = process.env.PORT || 3000;
app.listen(port, () => console.log(`API listening on :${port}`));
```

**Why this prevents “5 concurrent requests buy the last item”:**  
All concurrent purchases for the same `productId` must acquire the same row lock (`FOR UPDATE`). Only one will see `stock=1` and succeed; the next will see the updated `stock=0` and be rejected before writing—so stock never becomes negative.

