## 3) React UI Component (Vite + React) — simulate concurrent purchase requests

> This fires N fetch calls “at once” using `Promise.allSettled()` to simulate concurrency from the client side.

### `ConcurrentPurchaseTester.jsx`
```jsx
import React, { useMemo, useState } from "react";

export default function ConcurrentPurchaseTester() {
  const [baseUrl, setBaseUrl] = useState("http://localhost:3000");
  const [productId, setProductId] = useState(1);
  const [quantity, setQuantity] = useState(1);
  const [concurrency, setConcurrency] = useState(5);
  const [results, setResults] = useState([]);
  const [running, setRunning] = useState(false);

  const summary = useMemo(() => {
    const ok = results.filter(r => r.ok).length;
    const fail = results.length - ok;
    const lowStockAlerts = results.filter(r => r.ok && r.lowStockAlertTriggered).length;
    return { ok, fail, lowStockAlerts };
  }, [results]);

  async function runConcurrentPurchase() {
    setRunning(true);
    setResults([]);

    const calls = Array.from({ length: concurrency }, (_, i) => (async () => {
      const startedAt = Date.now();
      try {
        const resp = await fetch(`${baseUrl}/api/purchase`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ productId: Number(productId), quantity: Number(quantity) }),
        });
        const data = await resp.json().catch(() => ({}));
        return {
          idx: i + 1,
          httpStatus: resp.status,
          durationMs: Date.now() - startedAt,
          ok: resp.ok && data.ok === true,
          ...data,
        };
      } catch (e) {
        return {
          idx: i + 1,
          httpStatus: 0,
          durationMs: Date.now() - startedAt,
          ok: false,
          error: "Network error",
          details: e.message,
        };
      }
    })());

    const settled = await Promise.allSettled(calls);
    const normalized = settled.map(s => (s.status === "fulfilled" ? s.value : {
      ok: false,
      error: "Promise rejected",
      details: String(s.reason),
    }));

    // show fastest first
    normalized.sort((a, b) => (a.durationMs ?? 0) - (b.durationMs ?? 0));
    setResults(normalized);
    setRunning(false);
  }

  return (
    <div style={{ padding: 16, maxWidth: 900 }}>
      <h2>Concurrent Purchase Tester</h2>

      <div style={{ display: "grid", gap: 8, gridTemplateColumns: "1fr 1fr" }}>
        <label>
          API Base URL
          <input
            value={baseUrl}
            onChange={(e) => setBaseUrl(e.target.value)}
            style={{ width: "100%" }}
          />
        </label>

        <div />

        <label>
          Product ID
          <input
            type="number"
            value={productId}
            onChange={(e) => setProductId(Number(e.target.value))}
            style={{ width: "100%" }}
          />
        </label>

        <label>
          Quantity per request
          <input
            type="number"
            value={quantity}
            onChange={(e) => setQuantity(Number(e.target.value))}
            style={{ width: "100%" }}
          />
        </label>

        <label>
          Concurrency (number of parallel requests)
          <input
            type="number"
            value={concurrency}
            onChange={(e) => setConcurrency(Number(e.target.value))}
            style={{ width: "100%" }}
          />
        </label>

        <div style={{ display: "flex", alignItems: "end" }}>
          <button onClick={runConcurrentPurchase} disabled={running} style={{ width: "100%" }}>
            {running ? "Running..." : "Run Concurrent Purchase"}
          </button>
        </div>
      </div>

      <div style={{ marginTop: 16 }}>
        <strong>Summary:</strong>{" "}
        Success={summary.ok}, Fail={summary.fail}, LowStockAlerts={summary.lowStockAlerts}
      </div>

      <hr />

      <div style={{ display: "grid", gap: 8 }}>
        {results.map((r, idx) => (
          <div key={idx} style={{ border: "1px solid #ddd", borderRadius: 8, padding: 12 }}>
            <div style={{ display: "flex", justifyContent: "space-between", gap: 12 }}>
              <strong>
                Req #{r.idx ?? "?"} — {r.ok ? "✅ OK" : "❌ FAIL"} (HTTP {r.httpStatus})
              </strong>
              <span>{r.durationMs} ms</span>
            </div>

            <pre style={{ marginTop: 8, whiteSpace: "pre-wrap" }}>
{JSON.stringify(r, null, 2)}
            </pre>
          </div>
        ))}
      </div>
    </div>
  );
}
```

### Use it in `App.jsx`
```jsx
import React from "react";
import ConcurrentPurchaseTester from "./ConcurrentPurchaseTester.jsx";

export default function App() {
  return <ConcurrentPurchaseTester />;
}
```

