## `docker-compose.yml`
```yaml
services:
  db:
    image: postgres:16-alpine
    container_name: inventory_db
    environment:
      POSTGRES_USER: postgres
      POSTGRES_PASSWORD: postgres
      POSTGRES_DB: inventory
    ports:
      - "5432:5432"
    volumes:
      - db_data:/var/lib/postgresql/data
      - ./db/init.sql:/docker-entrypoint-initdb.d/init.sql:ro
    healthcheck:
      test: ["CMD-SHELL", "pg_isready -U postgres -d inventory"]
      interval: 5s
      timeout: 5s
      retries: 20

  api:
    build:
      context: ./backend
      dockerfile: Dockerfile
    container_name: inventory_api
    environment:
      PORT: 3000
      DATABASE_URL: postgres://postgres:postgres@db:5432/inventory
      NODE_ENV: production
    ports:
      - "3000:3000"
    depends_on:
      db:
        condition: service_healthy

  web:
    build:
      context: ./frontend
      dockerfile: Dockerfile
    container_name: inventory_web
    environment:
      # Vite runs in the container; proxy is configured in vite.config.js to reach "api" service
      VITE_API_BASE: ""
    ports:
      - "5173:5173"
    depends_on:
      - api

volumes:
  db_data:
```

