## `backend/app.js`
```js
// app.js (CommonJS)
const express = require("express");
const cors = require("cors");
const { pool } = require("./db");

const app = express();
app.use(express.json());

// If you use Vite proxy, CORS isn't needed, but keeping it makes direct calls easier.
app.use(cors({ origin: true }));

app.get("/health", (_, res) => res.json({ ok: true }));

/**
 * GET /api/products/:id
 * Helpful for testing stock live from the UI.
 */
app.get("/api/products/:id", async (req, res) => {
  const productId = Number(req.params.id);
  if (!Number.isInteger(productId) || productId <= 0) {
    return res.status(400).json({ error: "Invalid productId" });
  }

  const client = await pool.connect();
  try {
    const p = await client.query(
      `SELECT id, sku, name, stock, low_stock_threshold, updated_at FROM products WHERE id = $1`,
      [productId]
    );
    if (p.rows.length === 0) return res.status(404).json({ error: "Product not found" });

    const logs = await client.query(
      `SELECT id, type, quantity, note, created_at
       FROM inventory_log
       WHERE product_id = $1
       ORDER BY created_at DESC
       LIMIT 20`,
      [productId]
    );

    return res.json({ product: p.rows[0], recentLogs: logs.rows });
  } catch (err) {
    return res.status(500).json({ error: "Failed to fetch product", details: err.message });
  } finally {
    client.release();
  }
});

/**
 * POST /api/purchase
 * Body: { productId: number, quantity: number }
 *
 * Concurrency + atomicity:
 * - Row lock via SELECT ... FOR UPDATE
 * - Validate BEFORE writing (overselling prevention)
 * - Stock update + SALE log in same transaction (all-or-nothing)
 * - Low stock alert when remainingStock <= 5 (STRICT <= as required)
 */
app.post("/api/purchase", async (req, res) => {
  const productId = Number(req.body.productId);
  const quantity = Number(req.body.quantity);

  if (!Number.isInteger(productId) || productId <= 0) {
    return res.status(400).json({ error: "Invalid productId" });
  }
  if (!Number.isInteger(quantity) || quantity <= 0) {
    return res.status(400).json({ error: "Invalid quantity" });
  }

  const client = await pool.connect();
  try {
    await client.query("BEGIN");

    // Lock the product row to serialize concurrent purchases
    const { rows } = await client.query(
      `
      SELECT id, stock, low_stock_threshold
      FROM products
      WHERE id = $1
      FOR UPDATE
      `,
      [productId]
    );

    if (rows.length === 0) {
      await client.query("ROLLBACK");
      return res.status(404).json({ error: "Product not found" });
    }

    const product = rows[0];

    // Overselling prevention: validate before any write operation
    if (quantity > product.stock) {
      await client.query("ROLLBACK");
      return res.status(409).json({
        error: "Insufficient stock",
        available: product.stock,
        requested: quantity
      });
    }

    const remainingStock = product.stock - quantity;

    // Write: update stock
    await client.query(`UPDATE products SET stock = $1 WHERE id = $2`, [remainingStock, productId]);

    // Write: SALE log (same transaction -> atomic)
    await client.query(
      `
      INSERT INTO inventory_log (product_id, type, quantity, note)
      VALUES ($1, 'SALE', $2, $3)
      `,
      [productId, quantity, `Purchase deducted ${quantity}`]
    );

    // Low stock alert trigger: STRICT <= 5 as specified
    const threshold = 5;
    const lowStockAlertTriggered = remainingStock <= threshold;

    if (lowStockAlertTriggered) {
      await client.query(
        `
        INSERT INTO inventory_log (product_id, type, quantity, note)
        VALUES ($1, 'LOW_STOCK_ALERT', 1, $2)
        `,
        [productId, `Low stock alert: remaining=${remainingStock} (<= ${threshold})`]
      );
    }

    await client.query("COMMIT");

    return res.json({
      ok: true,
      productId,
      purchased: quantity,
      remainingStock,
      lowStockAlertTriggered,
      lowStockThresholdUsed: threshold
    });
  } catch (err) {
    // Any failure (including log insert failure) rolls back the stock update
    try {
      await client.query("ROLLBACK");
    } catch (_) {}
    return res.status(500).json({
      error: "Purchase failed (rolled back)",
      details: err.message
    });
  } finally {
    client.release();
  }
});

/**
 * POST /api/restore
 * Body: { productId: number, quantity: number, reason?: string }
 *
 * Stock restoration on cancellation/return with a "RESTOCK/RETURN" log entry.
 * Uses FOR UPDATE for correctness under concurrency.
 */
app.post("/api/restore", async (req, res) => {
  const productId = Number(req.body.productId);
  const quantity = Number(req.body.quantity);
  const reason = typeof req.body.reason === "string" ? req.body.reason : "Cancellation/Return";

  if (!Number.isInteger(productId) || productId <= 0) {
    return res.status(400).json({ error: "Invalid productId" });
  }
  if (!Number.isInteger(quantity) || quantity <= 0) {
    return res.status(400).json({ error: "Invalid quantity" });
  }

  const client = await pool.connect();
  try {
    await client.query("BEGIN");

    const { rows } = await client.query(
      `SELECT id, stock FROM products WHERE id = $1 FOR UPDATE`,
      [productId]
    );

    if (rows.length === 0) {
      await client.query("ROLLBACK");
      return res.status(404).json({ error: "Product not found" });
    }

    const currentStock = rows[0].stock;
    const newStock = currentStock + quantity;

    await client.query(`UPDATE products SET stock = $1 WHERE id = $2`, [newStock, productId]);

    await client.query(
      `
      INSERT INTO inventory_log (product_id, type, quantity, note)
      VALUES ($1, 'RESTOCK/RETURN', $2, $3)
      `,
      [productId, quantity, reason]
    );

    await client.query("COMMIT");
    return res.json({ ok: true, productId, restored: quantity, newStock });
  } catch (err) {
    try {
      await client.query("ROLLBACK");
    } catch (_) {}
    return res.status(500).json({ error: "Restore failed (rolled back)", details: err.message });
  } finally {
    client.release();
  }
});

const port = Number(process.env.PORT || 3000);
app.listen(port, () => console.log(`API listening on :${port}`));
```

