          return {
            idx: i + 1,
            httpStatus: resp.status,
            durationMs: Date.now() - startedAt,
            ok: resp.ok && data.ok === true,
            ...data
          };
        } catch (e) {
          return {
            idx: i + 1,
            httpStatus: 0,
            durationMs: Date.now() - startedAt,
            ok: false,
            error: "Network error",
            details: e.message
          };
        }
