"frontend/src/ConcurrentPurchaseTester.jsx": """import React, { useMemo, useState } from "react";

export default function ConcurrentPurchaseTester() {
  // If baseUrl is empty, requests go to same origin (Vite) and proxy -> backend via vite.config.js
  const envBase = (import.meta?.env?.VITE_API_BASE ?? "").toString();
  const [baseUrl, setBaseUrl] = useState(envBase);
  const [productId, setProductId] = useState(1);
  const [quantity, setQuantity] = useState(1);
  const [concurrency, setConcurrency] = useState(5);
  const [results, setResults] = useState([]);
  const [running, setRunning] = useState(false);
  const [productInfo, setProductInfo] = useState(null);

  const summary = useMemo(() => {
    const ok = results.filter((r) => r.ok).length;
    const fail = results.length - ok;
    const lowStockAlerts = results.filter((r) => r.ok && r.lowStockAlertTriggered).length;
    return { ok, fail, lowStockAlerts };
  }, [results]);

  function api(path) {
    return `${baseUrl}${path}`;
  }

  async function refreshProduct() {
    setProductInfo(null);
    try {
      const resp = await fetch(api(`/api/products/${Number(productId)}`));
      const data = await resp.json();
      setProductInfo({ httpStatus: resp.status, ok: resp.ok, ...data });
    } catch (e) {
      setProductInfo({ ok: false, error: "Network error", details: e.message });
    }
  }

  async function runConcurrentPurchase() {
    setRunning(true);
    setResults([]);

    const calls = Array.from({ length: concurrency }, (_, i) =>
      (async () => {
        const startedAt = Date.now();
        try {
          const resp = await fetch(api("/api/purchase"), {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({ productId: Number(productId), quantity: Number(quantity) })
          });
          const data = await resp.json().catch(() => ({}));
          return {
            idx: i + 1,
            httpStatus: resp.status,
            durationMs: Date.now() - startedAt,
            ok: resp.ok && data.ok === true,
            ...data
          };
        } catch (e) {
          return {
            idx: i + 1,
            httpStatus: 0,
            durationMs: Date.now() - startedAt,
            ok: false,
            error: "Network error",
            details: e.message
          };
        }
      })()
    );

    const settled = await Promise.allSettled(calls);
    const normalized = settled.map((s) =>
      s.status === "fulfilled"
        ? s.value
        : { ok: false, error: "Promise rejected", details: String(s.reason) }
    );

    normalized.sort((a, b) => (a.durationMs ?? 0) - (b.durationMs ?? 0));
    setResults(normalized);
    setRunning(false);
    refreshProduct();
  }

  async function restoreOne() {
    const startedAt = Date.now();
    try {
      const resp = await fetch(api("/api/restore"), {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          productId: Number(productId),
          quantity: Number(quantity),
          reason: "Manual restore from UI"
        })
      });
      const data = await resp.json().catch(() => ({}));
      setResults((prev) => [
        {
          idx: `RESTORE-${prev.length + 1}`,
          httpStatus: resp.status,
          durationMs: Date.now() - startedAt,
          ok: resp.ok && data.ok === true,
          ...data
        },
        ...prev
      ]);
    } catch (e) {
      setResults((prev) => [
        {
          idx: `RESTORE-${prev.length + 1}`,
          httpStatus: 0,
          durationMs: Date.now() - startedAt,
          ok: false,
          error: "Network error",
          details: e.message
        },
        ...prev
      ]);
    } finally {
      refreshProduct();
    }
  }

  return (
    <div style={{ padding: 16, maxWidth: 980, fontFamily: "system-ui, -apple-system, Segoe UI, Roboto" }}>
      <h2 style={{ marginTop: 0 }}>Inventory Concurrency Tester</h2>

      <div style={{ display: "grid", gap: 10, gridTemplateColumns: "1fr 1fr" }}>
        <label>
          API Base URL (leave blank to use Vite proxy)
          <input
            value={baseUrl}
            onChange={(e) => setBaseUrl(e.target.value)}
            placeholder=""
            style={{ width: "100%" }}
          />
        </label>

        <div />

        <label>
          Product ID
          <input
            type="number"
            value={productId}
            onChange={(e) => setProductId(Number(e.target.value))}
            style={{ width: "100%" }}
          />
        </label>

        <label>
          Quantity per request
          <input
            type="number"
            value={quantity}
            onChange={(e) => setQuantity(Number(e.target.value))}
            style={{ width: "100%" }}
          />
        </label>

        <label>
          Concurrency (parallel requests)
          <input
            type="number"
            value={concurrency}
            onChange={(e) => setConcurrency(Number(e.target.value))}
            style={{ width: "100%" }}
          />
        </label>

        <div style={{ display: "flex", gap: 10, alignItems: "end" }}>
          <button onClick={refreshProduct} disabled={running} style={{ flex: 1 }}>
            Refresh Product
          </button>
          <button onClick={restoreOne} disabled={running} style={{ flex: 1 }}>
            Restore (RESTOCK/RETURN)
          </button>
          <button onClick={runConcurrentPurchase} disabled={running} style={{ flex: 1 }}>
            {running ? "Running..." : "Run Concurrent Purchase"}
          </button>
        </div>
      </div>

      <div style={{ marginTop: 14 }}>
        <strong>Summary:</strong> Success={summary.ok}, Fail={summary.fail}, LowStockAlerts={summary.lowStockAlerts}
      </div>

      <div style={{ marginTop: 10, padding: 12, border: "1px solid #ddd", borderRadius: 8 }}>
        <strong>Product Snapshot</strong>
        <pre style={{ marginTop: 8, whiteSpace: "pre-wrap" }}>
{productInfo ? JSON.stringify(productInfo, null, 2) : "Click 'Refresh Product' to load."}
        </pre>
      </div>

      <hr style={{ margin: "16px 0" }} />

      <div style={{ display: "grid", gap: 8 }}>
        {results.map((r, idx) => (
          <div key={idx} style={{ border: "1px solid #ddd", borderRadius: 8, padding: 12 }}>
            <div style={{ display: "flex", justifyContent: "space-between", gap: 12 }}>
              <strong>
                Req #{r.idx ?? "?"} — {r.ok ? "✅ OK" : "❌ FAIL"} (HTTP {r.httpStatus})
              </strong>
              <span>{r.durationMs} ms</span>
            </div>
            <pre style={{ marginTop: 8, whiteSpace: "pre-wrap" }}>
{JSON.stringify(r, null, 2)}
            </pre>
          </div>
        ))}
      </div>

      <p style={{ marginTop: 16, color: "#555" }}>
        Tips:
        <br />• Low Stock Alert check: start at stock=6, buy 1 =&gt; remaining 5 =&gt; alert should trigger.
        <br />• Race Condition check: set stock=1, concurrency=5, quantity=1 =&gt; only one succeeds.
      </p>
    </div>
  );
}
"""
