import React, { useEffect, useMemo, useRef, useState } from "react";

/**
 * Tailwind Dashboard App for Inventory Management
 *
 * - Data Consistency indicators:
 *   - Each transaction has a client-generated txId
 *   - Sync status: PENDING -> COMMITTED / REJECTED / ROLLED_BACK
 *   - After success, UI updates stock immediately (optimistic) and then refreshes from server
 *
 * - Concurrency stress test:
 *   - Fires 5 concurrent /api/purchase requests in parallel
 *   - Shows results as they arrive (real-time list)
 */

function nowIsoShort() {
  const d = new Date();
  return d.toISOString().replace("T", " ").slice(0, 19);
}

function makeTxId() {
  // Prefer crypto.randomUUID if available
  if (typeof crypto !== "undefined" && crypto.randomUUID) return crypto.randomUUID();
  return `tx_${Date.now()}_${Math.random().toString(16).slice(2)}`;
}

function badgeForLogType(type) {
  if (type === "LOW_STOCK_ALERT") return "bg-blue-50 text-blue-700 ring-1 ring-blue-200";
  if (type === "RESTOCK/RETURN") return "bg-green-50 text-green-700 ring-1 ring-green-200";
  if (type === "SALE") return "bg-blue-50 text-blue-700 ring-1 ring-blue-200";
  return "bg-slate-50 text-slate-700 ring-1 ring-slate-200";
}

function badgeForTxStatus(status) {
  if (status === "COMMITTED") return "bg-green-50 text-green-700 ring-1 ring-green-200";
  if (status === "PENDING") return "bg-blue-50 text-blue-700 ring-1 ring-blue-200";
  if (status === "REJECTED") return "bg-red-50 text-red-700 ring-1 ring-red-200";
  if (status === "ROLLED_BACK") return "bg-red-50 text-red-700 ring-1 ring-red-200";
  return "bg-slate-50 text-slate-700 ring-1 ring-slate-200";
}

export default function App() {
  // If VITE_API_BASE is empty, we assume Vite proxy (/api -> backend) is configured.
  const envBase = (import.meta?.env?.VITE_API_BASE ?? "").toString();
  const [apiBase, setApiBase] = useState(envBase);

  // In your seeded demo, productId=1 exists. You can expand this to multiple IDs later.
  const [productIds, setProductIds] = useState([1]);
  const [productsById, setProductsById] = useState({}); // { [id]: product }
  const [recentLogsByProductId, setRecentLogsByProductId] = useState({}); // { [id]: logs[] }

  const [qty, setQty] = useState(1);
  const [stressQty, setStressQty] = useState(1);

  const [txList, setTxList] = useState([]); // newest first
  const txListRef = useRef(txList);
  useEffect(() => {
    txListRef.current = txList;
  }, [txList]);

  const [loading, setLoading] = useState(false);
  const [lastSyncAt, setLastSyncAt] = useState(null);

  // Drawer: Inventory Logs
  const [logsOpen, setLogsOpen] = useState(false);
  const [logsProductId, setLogsProductId] = useState(1);

  function api(path) {
    return `${apiBase}${path}`;
  }

  async function fetchProductAndLogs(id) {
    const resp = await fetch(api(`/api/products/${id}`));
    const data = await resp.json();
    if (!resp.ok) throw new Error(data?.error || `Failed to load product ${id}`);
    return data; // { product, recentLogs }
  }

  async function refreshAll() {
    setLoading(true);
    try {
      const results = await Promise.allSettled(productIds.map((id) => fetchProductAndLogs(id)));
      const nextProducts = { ...productsById };
      const nextLogs = { ...recentLogsByProductId };

      for (let i = 0; i < results.length; i++) {
        const id = productIds[i];
        const r = results[i];
        if (r.status === "fulfilled") {
          nextProducts[id] = r.value.product;
          nextLogs[id] = r.value.recentLogs || [];
        }
      }

      setProductsById(nextProducts);
      setRecentLogsByProductId(nextLogs);
      setLastSyncAt(nowIsoShort());
    } catch (e) {
      // ignore; surfaced in UI via toast-ish tx rows if needed
    } finally {
      setLoading(false);
    }
  }

  useEffect(() => {
    refreshAll();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const products = useMemo(() => {
    return productIds
      .map((id) => productsById[id])
      .filter(Boolean)
      .sort((a, b) => a.id - b.id);
  }, [productIds, productsById]);

  const dashboard = useMemo(() => {
    const totalStock = products.reduce((sum, p) => sum + (p.stock ?? 0), 0);
    const outOfStock = products.filter((p) => (p.stock ?? 0) === 0).length;

    let recentAlerts = 0;
    for (const p of products) {
      const logs = recentLogsByProductId[p.id] || [];
      recentAlerts += logs.filter((l) => l.type === "LOW_STOCK_ALERT").length;
    }

    return { totalStock, outOfStock, recentAlerts };
  }, [products, recentLogsByProductId]);

  function upsertTx(txId, patch) {
    setTxList((prev) => {
      const idx = prev.findIndex((t) => t.txId === txId);
      if (idx === -1) return [{ txId, ...patch }, ...prev];
      const copy = prev.slice();
      copy[idx] = { ...copy[idx], ...patch };
      // keep newest first
      return copy.sort((a, b) => (b.createdAtMs ?? 0) - (a.createdAtMs ?? 0));
    });
  }

  async function purchase(productId, quantity, mode = "single") {
    const txId = makeTxId();
    const createdAtMs = Date.now();

    // Create a visible pending transaction entry immediately
    upsertTx(txId, {
      txId,
      createdAt: nowIsoShort(),
      createdAtMs,
      productId,
      quantity,
      mode,
      status: "PENDING",
      httpStatus: null,
      message: "Sending request...",
      syncIndicator: "pending",
      remainingStock: null,
      lowStockAlertTriggered: null,
    });

    // Optimistic UI update (immediate stock decrement), then verify with server refresh.
    // This gives the "no full page refresh" requirement while still reconciling canonical state.
    const p = productsById[productId];
    if (p && typeof p.stock === "number" && quantity > 0) {
      setProductsById((prev) => ({
        ...prev,
        [productId]: { ...prev[productId], stock: Math.max(0, prev[productId].stock - quantity) },
      }));
    }

    try {
      const resp = await fetch(api("/api/purchase"), {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        // txId is client-generated correlation id; backend currently ignores it, but UI uses it.
        body: JSON.stringify({ productId, quantity, txId }),
      });

      const data = await resp.json().catch(() => ({}));

      if (resp.ok && data.ok === true) {
        upsertTx(txId, {
          status: "COMMITTED",
          httpStatus: resp.status,
          message: "Committed (stock + logs written atomically)",
          syncIndicator: "committed",
          remainingStock: data.remainingStock,
          lowStockAlertTriggered: !!data.lowStockAlertTriggered,
        });

        // Pull canonical state + logs from server immediately (no page refresh)
        const fresh = await fetchProductAndLogs(productId);
        setProductsById((prev) => ({ ...prev, [productId]: fresh.product }));
        setRecentLogsByProductId((prev) => ({ ...prev, [productId]: fresh.recentLogs || [] }));
        setLastSyncAt(nowIsoShort());
      } else {
        // Rejected (e.g., insufficient stock / 409)
        upsertTx(txId, {
          status: "REJECTED",
          httpStatus: resp.status,
          message: data?.error || "Rejected",
          syncIndicator: "rejected",
        });

        // Reconcile state from server (undo optimistic drift)
        const fresh = await fetchProductAndLogs(productId);
        setProductsById((prev) => ({ ...prev, [productId]: fresh.product }));
        setRecentLogsByProductId((prev) => ({ ...prev, [productId]: fresh.recentLogs || [] }));
        setLastSyncAt(nowIsoShort());
      }
    } catch (e) {
      // Network/unknown error => treat as rolled back/unknown; reconcile with server
      upsertTx(txId, {
        status: "ROLLED_BACK",
        httpStatus: 0,
        message: `Network error: ${e.message}`,
        syncIndicator: "rolled_back",
      });

      try {
        const fresh = await fetchProductAndLogs(productId);
        setProductsById((prev) => ({ ...prev, [productId]: fresh.product }));
        setRecentLogsByProductId((prev) => ({ ...prev, [productId]: fresh.recentLogs || [] }));
        setLastSyncAt(nowIsoShort());
      } catch (_) {
        // ignore
      }
    }

    return txId;
  }

  async function restore(productId, quantity) {
    const txId = makeTxId();
    const createdAtMs = Date.now();

    upsertTx(txId, {
      txId,
      createdAt: nowIsoShort(),
      createdAtMs,
      productId,
      quantity,
      mode: "restore",
      status: "PENDING",
      httpStatus: null,
      message: "Sending restoration...",
      syncIndicator: "pending",
    });

    // Optimistic update (green semantics)
    const p = productsById[productId];
    if (p && typeof p.stock === "number" && quantity > 0) {
      setProductsById((prev) => ({
        ...prev,
        [productId]: { ...prev[productId], stock: prev[productId].stock + quantity },
      }));
    }

    try {
      const resp = await fetch(api("/api/restore"), {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ productId, quantity, reason: "UI restore", txId }),
      });
      const data = await resp.json().catch(() => ({}));

      if (resp.ok && data.ok === true) {
        upsertTx(txId, {
          status: "COMMITTED",
          httpStatus: resp.status,
          message: "Restoration committed",
          syncIndicator: "committed",
        });

        const fresh = await fetchProductAndLogs(productId);
        setProductsById((prev) => ({ ...prev, [productId]: fresh.product }));
        setRecentLogsByProductId((prev) => ({ ...prev, [productId]: fresh.recentLogs || [] }));
        setLastSyncAt(nowIsoShort());
      } else {
        upsertTx(txId, {
          status: "REJECTED",
          httpStatus: resp.status,
          message: data?.error || "Restore rejected",
          syncIndicator: "rejected",
        });

        const fresh = await fetchProductAndLogs(productId);
        setProductsById((prev) => ({ ...prev, [productId]: fresh.product }));
        setRecentLogsByProductId((prev) => ({ ...prev, [productId]: fresh.recentLogs || [] }));
        setLastSyncAt(nowIsoShort());
      }
    } catch (e) {
      upsertTx(txId, {
        status: "ROLLED_BACK",
        httpStatus: 0,
        message: `Network error: ${e.message}`,
        syncIndicator: "rolled_back",
      });

      try {
        const fresh = await fetchProductAndLogs(productId);
        setProductsById((prev) => ({ ...prev, [productId]: fresh.product }));
        setRecentLogsByProductId((prev) => ({ ...prev, [productId]: fresh.recentLogs || [] }));
        setLastSyncAt(nowIsoShort());
      } catch (_) {}
    }
  }

  async function simulateStressTest(productId) {
    // Fire 5 concurrent purchases (race condition test)
    const N = 5;
    const promises = Array.from({ length: N }, () => purchase(productId, Number(stressQty), "stress"));

    // no need to await sequentially; we already update txList in real-time as each resolves
    await Promise.allSettled(promises);

