    try {
      const fresh = await fetchProductAndLogs(productId);
      setProductsById((prev) => ({ ...prev, [productId]: fresh.product }));
      setRecentLogsByProductId((prev) => ({ ...prev, [productId]: fresh.recentLogs || [] }));
      setLastSyncAt(nowIsoShort());
    } catch (_) {}
  }

  const activeLogs = useMemo(() => {
    const id = logsProductId;
    return recentLogsByProductId[id] || [];
  }, [logsProductId, recentLogsByProductId]);

  return (
    <div className="min-h-screen bg-slate-50 text-slate-900">
      {/* Top bar */}
      <header className="sticky top-0 z-30 border-b border-slate-200 bg-white/80 backdrop-blur">
        <div className="mx-auto flex max-w-7xl items-center justify-between px-4 py-3 md:px-6">
          <div className="flex items-center gap-3">
            <div className="h-10 w-10 rounded-2xl bg-slate-900 text-white grid place-items-center font-semibold">
              IM
            </div>
            <div>
              <div className="text-sm font-semibold">Inventory Dashboard</div>
              <div className="text-xs text-slate-500">
                Concurrency-safe • Atomic transactions • Consistency indicators
              </div>
            </div>
          </div>

          <div className="flex items-center gap-3">
            <div className="hidden md:flex items-center gap-2 rounded-xl border border-slate-200 bg-white px-3 py-2">
              <span className="text-xs text-slate-500">API Base</span>
              <input
                className="w-64 text-xs outline-none"
                placeholder="(blank uses Vite proxy)"
                value={apiBase}
                onChange={(e) => setApiBase(e.target.value)}
              />
            </div>

            <button
              onClick={() => refreshAll()}
              className="rounded-xl border border-slate-200 bg-white px-3 py-2 text-sm hover:bg-slate-50 active:scale-[0.99]"
            >
              {loading ? "Syncing..." : "Sync Now"}
            </button>

            <div className="hidden sm:flex items-center gap-2 rounded-xl bg-slate-900 px-3 py-2 text-xs text-white">
              <span className="opacity-80">Last Sync</span>
              <span className="font-semibold">{lastSyncAt || "—"}</span>
            </div>
          </div>
        </div>
      </header>

      <main className="mx-auto max-w-7xl px-4 py-6 md:px-6">
        {/* Summary cards */}
        <section className="grid grid-cols-1 gap-4 md:grid-cols-3">
          <div className="rounded-2xl border border-slate-200 bg-white p-4 shadow-sm">
            <div className="text-xs text-slate-500">Total Stock</div>
            <div className="mt-2 text-2xl font-semibold">{dashboard.totalStock}</div>
            <div className="mt-1 text-xs text-slate-500">Sum across loaded products</div>
          </div>

          <div className="rounded-2xl border border-slate-200 bg-white p-4 shadow-sm">
            <div className="text-xs text-slate-500">Out of Stock Items</div>
            <div className="mt-2 text-2xl font-semibold">{dashboard.outOfStock}</div>
            <div className="mt-1 text-xs text-slate-500">Stock = 0</div>
          </div>

          <div className="rounded-2xl border border-slate-200 bg-white p-4 shadow-sm">
            <div className="text-xs text-slate-500">Recent Alerts</div>
            <div className="mt-2 text-2xl font-semibold">{dashboard.recentAlerts}</div>
            <div className="mt-1 text-xs text-slate-500">LOW_STOCK_ALERT entries (recent)</div>
          </div>
        </section>

        {/* Layout: table + side panel */}
        <section className="mt-6 grid grid-cols-1 gap-4 lg:grid-cols-3">
          {/* Product table & controls */}
          <div className="lg:col-span-2">
            <div className="rounded-2xl border border-slate-200 bg-white shadow-sm">
              <div className="flex flex-col gap-3 border-b border-slate-200 p-4 md:flex-row md:items-center md:justify-between">
                <div>
