app_jsx = r"""import React, { useEffect, useMemo, useRef, useState } from "react";

/**
 * Tailwind Dashboard App for Inventory Management
 *
 * - Data Consistency indicators:
 *   - Each transaction has a client-generated txId
 *   - Sync status: PENDING -> COMMITTED / REJECTED / ROLLED_BACK
 *   - After success, UI updates stock immediately (optimistic) and then refreshes from server
 *
 * - Concurrency stress test:
 *   - Fires 5 concurrent /api/purchase requests in parallel
 *   - Shows results as they arrive (real-time list)
 */

function nowIsoShort() {
  const d = new Date();
  return d.toISOString().replace("T", " ").slice(0, 19);
}

function makeTxId() {
  // Prefer crypto.randomUUID if available
  if (typeof crypto !== "undefined" && crypto.randomUUID) return crypto.randomUUID();
  return `tx_${Date.now()}_${Math.random().toString(16).slice(2)}`;
}

function badgeForLogType(type) {
  if (type === "LOW_STOCK_ALERT") return "bg-blue-50 text-blue-700 ring-1 ring-blue-200";
  if (type === "RESTOCK/RETURN") return "bg-green-50 text-green-700 ring-1 ring-green-200";
  if (type === "SALE") return "bg-blue-50 text-blue-700 ring-1 ring-blue-200";
  return "bg-slate-50 text-slate-700 ring-1 ring-slate-200";
}

function badgeForTxStatus(status) {
  if (status === "COMMITTED") return "bg-green-50 text-green-700 ring-1 ring-green-200";
  if (status === "PENDING") return "bg-blue-50 text-blue-700 ring-1 ring-blue-200";
  if (status === "REJECTED") return "bg-red-50 text-red-700 ring-1 ring-red-200";
  if (status === "ROLLED_BACK") return "bg-red-50 text-red-700 ring-1 ring-red-200";
  return "bg-slate-50 text-slate-700 ring-1 ring-slate-200";
}

export default function App() {
  // If VITE_API_BASE is empty, we assume Vite proxy (/api -> backend) is configured.
  const envBase = (import.meta?.env?.VITE_API_BASE ?? "").toString();
  const [apiBase, setApiBase] = useState(envBase);

  // In your seeded demo, productId=1 exists. You can expand this to multiple IDs later.
  const [productIds] = useState([1]);
  const [productsById, setProductsById] = useState({}); // { [id]: product }
  const [recentLogsByProductId, setRecentLogsByProductId] = useState({}); // { [id]: logs[] }

  const [qty, setQty] = useState(1);
  const [stressQty, setStressQty] = useState(1);

  const [txList, setTxList] = useState([]); // newest first
  const txListRef = useRef(txList);
  useEffect(() => {
    txListRef.current = txList;
  }, [txList]);

  const [loading, setLoading] = useState(false);
  const [lastSyncAt, setLastSyncAt] = useState(null);

  // Drawer: Inventory Logs
  const [logsOpen, setLogsOpen] = useState(false);
  const [logsProductId, setLogsProductId] = useState(1);

  function api(path) {
    return `${apiBase}${path}`;
  }

  async function fetchProductAndLogs(id) {
    const resp = await fetch(api(`/api/products/${id}`));
    const data = await resp.json();
    if (!resp.ok) throw new Error(data?.error || `Failed to load product ${id}`);
    return data; // { product, recentLogs }
  }

  async function refreshAll() {
    setLoading(true);
    try {
      const results = await Promise.allSettled(productIds.map((id) => fetchProductAndLogs(id)));
      const nextProducts = { ...productsById };
      const nextLogs = { ...recentLogsByProductId };

      for (let i = 0; i < results.length; i++) {
        const id = productIds[i];
        const r = results[i];
        if (r.status === "fulfilled") {
          nextProducts[id] = r.value.product;
          nextLogs[id] = r.value.recentLogs || [];
        }
      }

      setProductsById(nextProducts);
      setRecentLogsByProductId(nextLogs);
      setLastSyncAt(nowIsoShort());
    } catch (e) {
      // ignore; surfaced via tx rows if needed
    } finally {
      setLoading(false);
    }
  }

  useEffect(() => {
    refreshAll();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const products = useMemo(() => {
    return productIds
      .map((id) => productsById[id])
      .filter(Boolean)
      .sort((a, b) => a.id - b.id);
  }, [productIds, productsById]);

  const dashboard = useMemo(() => {
    const totalStock = products.reduce((sum, p) => sum + (p.stock ?? 0), 0);
    const outOfStock = products.filter((p) => (p.stock ?? 0) === 0).length;

    let recentAlerts = 0;
    for (const p of products) {
      const logs = recentLogsByProductId[p.id] || [];
      recentAlerts += logs.filter((l) => l.type === "LOW_STOCK_ALERT").length;
    }

    return { totalStock, outOfStock, recentAlerts };
  }, [products, recentLogsByProductId]);

  function upsertTx(txId, patch) {
    setTxList((prev) => {
      const idx = prev.findIndex((t) => t.txId === txId);
      if (idx === -1) return [{ txId, ...patch }, ...prev];
      const copy = prev.slice();
      copy[idx] = { ...copy[idx], ...patch };
      // keep newest first
      return copy.sort((a, b) => (b.createdAtMs ?? 0) - (a.createdAtMs ?? 0));
    });
  }

  async function purchase(productId, quantity, mode = "single") {
    const txId = makeTxId();
    const createdAtMs = Date.now();

    // Create a visible pending transaction entry immediately
    upsertTx(txId, {
      txId,
      createdAt: nowIsoShort(),
      createdAtMs,
      productId,
      quantity,
      mode,
      status: "PENDING",
      httpStatus: null,
      message: "Sending request...",
      syncIndicator: "pending",
      remainingStock: null,
      lowStockAlertTriggered: null
    });

    // Optimistic UI update, then verify with server refresh.
    const p = productsById[productId];
    if (p && typeof p.stock === "number" && quantity > 0) {
      setProductsById((prev) => ({
        ...prev,
        [productId]: { ...prev[productId], stock: Math.max(0, prev[productId].stock - quantity) }
      }));
    }

    try {
      const resp = await fetch(api("/api/purchase"), {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        // txId is client-generated correlation id; backend ignores it, but UI uses it.
        body: JSON.stringify({ productId, quantity, txId })
      });

      const data = await resp.json().catch(() => ({}));

      if (resp.ok && data.ok === true) {
        upsertTx(txId, {
          status: "COMMITTED",
          httpStatus: resp.status,
          message: "Committed (stock + logs written atomically)",
          syncIndicator: "committed",
          remainingStock: data.remainingStock,
          lowStockAlertTriggered: !!data.lowStockAlertTriggered
        });

        const fresh = await fetchProductAndLogs(productId);
        setProductsById((prev) => ({ ...prev, [productId]: fresh.product }));
        setRecentLogsByProductId((prev) => ({ ...prev, [productId]: fresh.recentLogs || [] }));
        setLastSyncAt(nowIsoShort());
      } else {
        upsertTx(txId, {
          status: "REJECTED",
          httpStatus: resp.status,
          message: data?.error || "Rejected",
          syncIndicator: "rejected"
        });

        const fresh = await fetchProductAndLogs(productId);
        setProductsById((prev) => ({ ...prev, [productId]: fresh.product }));
        setRecentLogsByProductId((prev) => ({ ...prev, [productId]: fresh.recentLogs || [] }));
        setLastSyncAt(nowIsoShort());
      }
    } catch (e) {
      upsertTx(txId, {
        status: "ROLLED_BACK",
        httpStatus: 0,
        message: `Network error: ${e.message}`,
        syncIndicator: "rolled_back"
      });

      try {
        const fresh = await fetchProductAndLogs(productId);
        setProductsById((prev) => ({ ...prev, [productId]: fresh.product }));
        setRecentLogsByProductId((prev) => ({ ...prev, [productId]: fresh.recentLogs || [] }));
        setLastSyncAt(nowIsoShort());
      } catch (_) {}
    }

    return txId;
  }

  async function restore(productId, quantity) {
    const txId = makeTxId();
    const createdAtMs = Date.now();

    upsertTx(txId, {
      txId,
      createdAt: nowIsoShort(),
      createdAtMs,
      productId,
      quantity,
      mode: "restore",
      status: "PENDING",
      httpStatus: null,
      message: "Sending restoration...",
      syncIndicator: "pending"
    });

    const p = productsById[productId];
    if (p && typeof p.stock === "number" && quantity > 0) {
      setProductsById((prev) => ({
        ...prev,
        [productId]: { ...prev[productId], stock: prev[productId].stock + quantity }
      }));
    }

    try {
      const resp = await fetch(api("/api/restore"), {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ productId, quantity, reason: "UI restore", txId })
      });
      const data = await resp.json().catch(() => ({}));

      if (resp.ok && data.ok === true) {
        upsertTx(txId, {
          status: "COMMITTED",
          httpStatus: resp.status,
          message: "Restoration committed",
          syncIndicator: "committed"
        });

        const fresh = await fetchProductAndLogs(productId);
        setProductsById((prev) => ({ ...prev, [productId]: fresh.product }));
        setRecentLogsByProductId((prev) => ({ ...prev, [productId]: fresh.recentLogs || [] }));
        setLastSyncAt(nowIsoShort());
      } else {
        upsertTx(txId, {
          status: "REJECTED",
          httpStatus: resp.status,
          message: data?.error || "Restore rejected",
          syncIndicator: "rejected"
        });

        const fresh = await fetchProductAndLogs(productId);
        setProductsById((prev) => ({ ...prev, [productId]: fresh.product }));
        setRecentLogsByProductId((prev) => ({ ...prev, [productId]: fresh.recentLogs || [] }));
        setLastSyncAt(nowIsoShort());
      }
    } catch (e) {
      upsertTx(txId, {
        status: "ROLLED_BACK",
        httpStatus: 0,
        message: `Network error: ${e.message}`,
        syncIndicator: "rolled_back"
      });

      try {
        const fresh = await fetchProductAndLogs(productId);
        setProductsById((prev) => ({ ...prev, [productId]: fresh.product }));
        setRecentLogsByProductId((prev) => ({ ...prev, [productId]: fresh.recentLogs || [] }));
        setLastSyncAt(nowIsoShort());
      } catch (_) {}
    }
  }

  async function simulateStressTest(productId) {
    const N = 5;
    const promises = Array.from({ length: N }, () =>
      purchase(productId, Number(stressQty), "stress")
    );

    await Promise.allSettled(promises);

    try {
      const fresh = await fetchProductAndLogs(productId);
      setProductsById((prev) => ({ ...prev, [productId]: fresh.product }));
      setRecentLogsByProductId((prev) => ({ ...prev, [productId]: fresh.recentLogs || [] }));
      setLastSyncAt(nowIsoShort());
    } catch (_) {}
  }

  const activeLogs = useMemo(() => {
    return recentLogsByProductId[logsProductId] || [];
  }, [logsProductId, recentLogsByProductId]);

  return (
    <div className="min-h-screen bg-slate-50 text-slate-900">
      {/* Top bar */}
      <header className="sticky top-0 z-30 border-b border-slate-200 bg-white/80 backdrop-blur">
        <div className="mx-auto flex max-w-7xl items-center justify-between px-4 py-3 md:px-6">
          <div className="flex items-center gap-3">
            <div className="grid h-10 w-10 place-items-center rounded-2xl bg-slate-900 font-semibold text-white">
              IM
            </div>
            <div>
              <div className="text-sm font-semibold">Inventory Dashboard</div>
              <div className="text-xs text-slate-500">
                Concurrency-safe • Atomic transactions • Consistency indicators
              </div>
            </div>
          </div>

          <div className="flex items-center gap-3">
            <div className="hidden items-center gap-2 rounded-xl border border-slate-200 bg-white px-3 py-2 md:flex">
              <span className="text-xs text-slate-500">API Base</span>
              <input
                className="w-64 text-xs outline-none"
                placeholder="(blank uses Vite proxy)"
                value={apiBase}
                onChange={(e) => setApiBase(e.target.value)}
              />
            </div>

            <button
              onClick={() => refreshAll()}
              className="rounded-xl border border-slate-200 bg-white px-3 py-2 text-sm hover:bg-slate-50 active:scale-[0.99]"
            >
              {loading ? "Syncing..." : "Sync Now"}
            </button>

            <div className="hidden items-center gap-2 rounded-xl bg-slate-900 px-3 py-2 text-xs text-white sm:flex">
              <span className="opacity-80">Last Sync</span>
              <span className="font-semibold">{lastSyncAt || "—"}</span>
            </div>
          </div>
        </div>
      </header>

      <main className="mx-auto max-w-7xl px-4 py-6 md:px-6">
        {/* Summary cards */}
        <section className="grid grid-cols-1 gap-4 md:grid-cols-3">
          <div className="rounded-2xl border border-slate-200 bg-white p-4 shadow-sm">
            <div className="text-xs text-slate-500">Total Stock</div>
            <div className="mt-2 text-2xl font-semibold">{dashboard.totalStock}</div>
            <div className="mt-1 text-xs text-slate-500">Sum across loaded products</div>
          </div>

          <div className="rounded-2xl border border-slate-200 bg-white p-4 shadow-sm">
            <div className="text-xs text-slate-500">Out of Stock Items</div>
            <div className="mt-2 text-2xl font-semibold">{dashboard.outOfStock}</div>
            <div className="mt-1 text-xs text-slate-500">Stock = 0</div>
          </div>

          <div className="rounded-2xl border border-slate-200 bg-white p-4 shadow-sm">
            <div className="text-xs text-slate-500">Recent Alerts</div>
            <div className="mt-2 text-2xl font-semibold">{dashboard.recentAlerts}</div>
            <div className="mt-1 text-xs text-slate-500">LOW_STOCK_ALERT entries (recent)</div>
          </div>
        </section>

        {/* Layout: table + side panel */}
        <section className="mt-6 grid grid-cols-1 gap-4 lg:grid-cols-3">
          {/* Product table & controls */}
          <div className="lg:col-span-2">
            <div className="rounded-2xl border border-slate-200 bg-white shadow-sm">
              <div className="flex flex-col gap-3 border-b border-slate-200 p-4 md:flex-row md:items-center md:justify-between">
                <div>
                  <div className="text-sm font-semibold">Products</div>
                  <div className="text-xs text-slate-500">
                    Rows turn <span className="font-semibold text-red-600">red</span> when stock ≤ 5.
                  </div>
                </div>

                <div className="flex flex-wrap items-center gap-2">
                  <label className="flex items-center gap-2 rounded-xl border border-slate-200 bg-white px-3 py-2 text-xs">
                    Qty
                    <input
                      type="number"
                      min={1}
                      className="w-16 rounded-lg border border-slate-200 px-2 py-1 text-xs outline-none"
                      value={qty}
                      onChange={(e) => setQty(Number(e.target.value))}
                    />
                  </label>
                </div>
              </div>

              <div className="overflow-x-auto">
                <table className="min-w-full text-left text-sm">
                  <thead className="bg-slate-50 text-xs text-slate-500">
                    <tr>
                      <th className="px-4 py-3">Product</th>
                      <th className="px-4 py-3">Stock</th>
                      <th className="px-4 py-3">Updated</th>
                      <th className="px-4 py-3 text-right">Actions</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-200">
                    {products.length === 0 ? (
                      <tr>
                        <td className="px-4 py-6 text-sm text-slate-500" colSpan={4}>
                          No products loaded. Seed productId=1 in DB, then click “Sync Now”.
                        </td>
                      </tr>
                    ) : (
                      products.map((p) => {
                        const isLow = (p.stock ?? 0) <= 5;
                        const rowTint = isLow ? "bg-red-50" : "bg-white";
                        const stockText = isLow ? "text-red-700" : "text-slate-900";
                        const stockBadge = isLow
                          ? "bg-red-100 text-red-700 ring-1 ring-red-200"
                          : "bg-slate-100 text-slate-700 ring-1 ring-slate-200";

                        return (
                          <tr key={p.id} className={`${rowTint} transition-colors`}>
                            <td className="px-4 py-4">
                              <div className="font-medium">{p.name || `Product #${p.id}`}</div>
                              <div className="text-xs text-slate-500">
                                ID: {p.id} • SKU: {p.sku || "—"}
                              </div>
                            </td>

                            <td className="px-4 py-4">
                              <div className={`inline-flex items-center gap-2 ${stockText}`}>
                                <span className={`rounded-full px-2 py-1 text-xs ${stockBadge}`}>
                                  {p.stock}
                                </span>
                                {isLow && (
                                  <span className="text-xs font-semibold text-red-600">≤ 5</span>
                                )}
                              </div>
                            </td>

                            <td className="px-4 py-4 text-xs text-slate-500">
                              {p.updated_at ? new Date(p.updated_at).toLocaleString() : "—"}
                            </td>

                            <td className="px-4 py-4">
                              <div className="flex flex-wrap justify-end gap-2">
                                <button
                                  onClick={() => {
                                    setLogsProductId(p.id);
                                    setLogsOpen(true);
                                  }}
                                  className="rounded-xl border border-slate-200 bg-white px-3 py-2 text-xs hover:bg-slate-50"
                                >
                                  View Logs
                                </button>

                                <button
                                  onClick={() => restore(p.id, Number(qty))}
                                  className="rounded-xl bg-green-600 px-3 py-2 text-xs font-semibold text-white hover:bg-green-700 active:scale-[0.99]"
                                  title="RESTOCK/RETURN"
                                >
                                  Restore
                                </button>

                                <button
                                  onClick={() => purchase(p.id, Number(qty), "single")}
                                  className="rounded-xl bg-slate-900 px-3 py-2 text-xs font-semibold text-white hover:bg-slate-800 active:scale-[0.99]"
                                  title="SALE"
                                >
                                  Buy
                                </button>
                              </div>
                            </td>
                          </tr>
                        );
                      })
                    )}
                  </tbody>
                </table>
              </div>
            </div>

            {/* Stress Test */}
            <div className="mt-4 rounded-2xl border border-slate-200 bg-white p-4 shadow-sm">
              <div className="flex flex-col gap-2 md:flex-row md:items-center md:justify-between">
                <div>
                  <div className="text-sm font-semibold">Simulate Stress Test</div>
                  <div className="text-xs text-slate-500">
                    Triggers <span className="font-semibold">5 concurrent</span> purchases (race condition test).
                  </div>
                </div>

                <div className="flex flex-wrap items-center gap-2">
                  <label className="flex items-center gap-2 rounded-xl border border-slate-200 bg-white px-3 py-2 text-xs">
                    Qty
                    <input
                      type="number"
                      min={1}
                      className="w-16 rounded-lg border border-slate-200 px-2 py-1 text-xs outline-none"
                      value={stressQty}
                      onChange={(e) => setStressQty(Number(e.target.value))}
                    />
                  </label>

                  <label className="flex items-center gap-2 rounded-xl border border-slate-200 bg-white px-3 py-2 text-xs">
                    Product ID
                    <select
                      className="rounded-lg border border-slate-200 px-2 py-1 text-xs outline-none"
                      value={logsProductId}
                      onChange={(e) => setLogsProductId(Number(e.target.value))}
                    >
                      {productIds.map((id) => (
                        <option key={id} value={id}>
                          {id}
                        </option>
                      ))}
                    </select>
                  </label>

                  <button
                    onClick={() => simulateStressTest(Number(logsProductId))}
                    className="rounded-xl bg-blue-600 px-3 py-2 text-xs font-semibold text-white hover:bg-blue-700 active:scale-[0.99]"
                  >
                    Run 5x Concurrent Purchases
                  </button>
                </div>
              </div>

              {/* Real-time results */}
              <div className="mt-4">
                <div className="mb-2 text-xs font-semibold text-slate-600">Transaction Stream</div>
                <div className="max-h-72 overflow-auto rounded-xl border border-slate-200 bg-slate-50">
                  {txList.length === 0 ? (
                    <div className="p-4 text-xs text-slate-500">No transactions yet.</div>
                  ) : (
                    <ul className="divide-y divide-slate-200">
                      {txList.map((t) => (
                        <li key={t.txId} className="p-3">
                          <div className="flex flex-col gap-1 md:flex-row md:items-center md:justify-between">
                            <div className="flex flex-wrap items-center gap-2">
                              <span
                                className={`rounded-full px-2 py-1 text-[11px] ${badgeForTxStatus(
                                  t.status
                                )}`}
                              >
                                {t.status}
                              </span>

                              {/* Transaction ID indicator */}
                              <span className="rounded-full bg-white px-2 py-1 text-[11px] text-slate-600 ring-1 ring-slate-200">
                                Tx: <span className="font-mono">{t.txId.slice(0, 8)}</span>
                              </span>

                              <span className="text-xs text-slate-600">
                                Product <span className="font-semibold">#{t.productId}</span> • Qty{" "}
                                <span className="font-semibold">{t.quantity}</span>
                              </span>

                              {typeof t.remainingStock === "number" && (
                                <span className="text-xs text-slate-600">
                                  Remaining: <span className="font-semibold">{t.remainingStock}</span>
                                </span>
                              )}

                              {t.lowStockAlertTriggered === true && (
                                <span className="rounded-full bg-red-100 px-2 py-1 text-[11px] font-semibold text-red-700 ring-1 ring-red-200">
                                  Low Stock Alert (≤ 5)
                                </span>
                              )}

                              {t.mode === "restore" && (
                                <span className="rounded-full bg-green-100 px-2 py-1 text-[11px] font-semibold text-green-700 ring-1 ring-green-200">
                                  Restoration
                                </span>
                              )}
                            </div>

                            <div className="flex items-center gap-2 text-xs text-slate-500">
                              <span>{t.createdAt}</span>
                              <span className="rounded-full bg-white px-2 py-1 text-[11px] ring-1 ring-slate-200">
                                HTTP {t.httpStatus ?? "—"}
                              </span>
                            </div>
                          </div>

                          <div className="mt-1 text-xs text-slate-600">
                            <span className="font-semibold text-slate-700">Sync:</span>{" "}
                            <span className="font-mono">{t.syncIndicator}</span> • {t.message}
                          </div>
                        </li>
                      ))}
                    </ul>
                  )}
                </div>

                <div className="mt-2 text-[11px] text-slate-500">
                  * “COMMITTED” indicates the backend transaction completed (stock update + logs written atomically).
                </div>
              </div>
            </div>
          </div>

          {/* Right panel: Quick Logs + Quick info */}
          <aside className="lg:col-span-1">
            <div className="rounded-2xl border border-slate-200 bg-white p-4 shadow-sm">
              <div className="flex items-center justify-between">
                <div>
                  <div className="text-sm font-semibold">Inventory Logs</div>
                  <div className="text-xs text-slate-500">
                    Scrollable view • Blue=info • Green=restoration • Red=low stock
                  </div>
                </div>
                <button
                  onClick={() => setLogsOpen(true)}
                  className="rounded-xl border border-slate-200 bg-white px-3 py-2 text-xs hover:bg-slate-50"
                >
                  Open Drawer
                </button>
              </div>

              <div className="mt-3 flex items-center gap-2">
                <span className="text-xs text-slate-500">Product</span>
                <select
                  className="rounded-xl border border-slate-200 px-3 py-2 text-xs outline-none"
                  value={logsProductId}
                  onChange={(e) => setLogsProductId(Number(e.target.value))}
                >
                  {productIds.map((id) => (
                    <option key={id} value={id}>
                      {id}
                    </option>
                  ))}
                </select>
              </div>

              <div className="mt-4 max-h-96 overflow-auto rounded-xl border border-slate-200 bg-slate-50">
                {activeLogs.length === 0 ? (
                  <div className="p-4 text-xs text-slate-500">No logs loaded yet. Click Sync Now.</div>
                ) : (
                  <ul className="divide-y divide-slate-200">
                    {activeLogs.map((l) => (
                      <li key={l.id} className="p-3">
                        <div className="flex items-center justify-between gap-2">
                          <span className={`rounded-full px-2 py-1 text-[11px] ${badgeForLogType(l.type)}`}>
                            {l.type}
                          </span>
                          <span className="text-[11px] text-slate-500">
                            {l.created_at ? new Date(l.created_at).toLocaleString() : "—"}
                          </span>
                        </div>
                        <div className="mt-1 text-xs text-slate-700">
                          Qty: <span className="font-semibold">{l.quantity}</span>
                        </div>
                        {l.note && <div className="mt-1 text-xs text-slate-600">{l.note}</div>}
                      </li>
                    ))}
                  </ul>
                )}
              </div>
            </div>
          </aside>
        </section>
      </main>

      {/* Logs Drawer */}
      {logsOpen && (
        <div className="fixed inset-0 z-40">
