                  </thead>
                  <tbody className="divide-y divide-slate-200">
                    {products.length === 0 ? (
                      <tr>
                        <td className="px-4 py-6 text-sm text-slate-500" colSpan={4}>
                          No products loaded. Seed productId=1 in DB, then click “Sync Now”.
                        </td>
                      </tr>
                    ) : (
