                  >
                    Run 5x Concurrent Purchases
                  </button>
                </div>
              </div>

              <div className="mt-4">
                <div className="mb-2 text-xs font-semibold text-slate-600">Transaction Stream</div>
                <div className="max-h-72 overflow-auto rounded-xl border border-slate-200 bg-slate-50">
                  {txList.length === 0 ? (
                    <div className="p-4 text-xs text-slate-500">No transactions yet.</div>
