                className="w-full rounded-xl bg-slate-900 px-3 py-2 text-xs font-semibold text-white hover:bg-slate-800"
              >
                Refresh Logs
              </button>

              <div className="mt-4 max-h-[calc(100vh-190px)] overflow-auto rounded-xl border border-slate-200 bg-slate-50">
                {activeLogs.length === 0 ? (
                  <div className="p-4 text-xs text-slate-500">No logs available.</div>
                ) : (
                  <ul className="divide-y divide-slate-200">
