                          </span>
                          <span className="text-[11px] text-slate-500">
                            {l.created_at ? new Date(l.created_at).toLocaleString() : "—"}
                          </span>
                        </div>
                        <div className="mt-1 text-xs text-slate-700">
                          Qty: <span className="font-semibold">{l.quantity}</span>
                        </div>
                        {l.note && <div className="mt-1 text-xs text-slate-600">{l.note}</div>}
                      </li>
                    ))}
                  </ul>
                )}
              </div>

              <div className="mt-3 text-[11px] text-slate-500">
                Color logic: <span className="font-semibold text-red-600">Red</span> when stock ≤ 5 •{" "}
                <span className="font-semibold text-green-600">Green</span> restoration •{" "}
                <span className="font-semibold text-blue-600">Blue</span> logs/info
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
